        right: 1.5rem;
        width: 44px;
        height: 44px;
        font-size: 1.25rem;
    }

    header h1 {
        font-size: 1.8rem;
        flex: 1 1 100%;
    }

    h2 {
        font-size: 1.5rem;
    }

    p {
        font-size: 1rem;
    }

    .cta-button {
        padding: 1rem 1.75rem;
        min-height: 48px;
        font-size: 0.95rem;
    }

    .hero-section {
        padding: 3.5rem 20px;
        border-radius: 12px;
    }

    .hero-section h2 {
        font-size: 2rem;
        margin-bottom: 1rem;
    }

    .hero-section p {
        font-size: 1rem;
        margin-bottom: 1.5rem;
    }

    .feature-grid {
        grid-template-columns: 1fr;
        gap: 1.5rem;
    }

    .menu-toggle {
        display: flex;
        align-items: center;
        justify-content: center;
        min-height: 48px;
        min-width: 48px;
    }

    header nav {
        width: 100%;
        order: 3;
    }

    header nav ul {
        flex-direction: column;
        gap: 1rem;
        padding: 1rem 0;
        border-top: 1px solid rgba(255, 255, 255, 0.2);
        margin-top: 1rem;
    }

    header nav ul[hidden] {
        display: none;
    }

    input[type="text"],
    input[type="email"],
    textarea {
        max-width: 100%;
    }

    .cta-button {
        width: 100%;
        max-width: 100%;
    }

    fieldset {
        padding: 1.5rem;
    }

    footer ul {
        flex-direction: column;
        gap: 1.5rem;
    }

    footer a {
        display: block;
        padding: 0.5rem 0;
    }

    .form-group {
        margin-bottom: 2rem;
    }

    .form-group input[aria-invalid="true"],
    .form-group textarea[aria-invalid="true"] {
        border-color: var(--error-color);
    }

    @media (prefers-color-scheme: dark) {
        .form-group input[aria-invalid="true"],
        .form-group textarea[aria-invalid="true"] {
            border-color: var(--error-dark);
        }
    }

    .testimonials-section {
        margin: 2rem 0;
        padding: 2rem 20px;
    }

    .testimonials-grid {
        grid-template-columns: 1fr;
        gap: 1.5rem;
    }

    footer > div {
        grid-template-columns: 1fr;
    }

    footer ul {
        flex-direction: column;
        gap: 0.75rem;
    }

    footer nav ul li {
        display: block;
        text-align: center;
        margin-bottom: 0.5rem;
    }

    .feature-card h3 {
        font-size: 1.1rem;
    }

    legend {
        font-size: 1.25rem;
        padding: 0 0.5rem;
    }
}

