        flex-direction: column;
        gap: 1rem;
        padding: 1rem 0;
        border-top: 1px solid rgba(255, 255, 255, 0.2);
        margin-top: 1rem;
    }

    header nav ul[hidden] {
        display: none;
    }

    input[type="text"],
    input[type="email"],
    textarea {
        max-width: 100%;
    }

    fieldset {
        padding: 1.5rem;
    }

    footer ul {
        flex-direction: column;
        gap: 1.5rem;
    }

    footer a {
        display: block;
        padding: 0.5rem 0;
    }

    .form-group {
        margin-bottom: 2rem;
    }

    .form-group input[aria-invalid="true"],
    .form-group textarea[aria-invalid="true"] {
        border-color: var(--error-color);
    }

    @media (prefers-color-scheme: dark) {
        .form-group input[aria-invalid="true"],
        .form-group textarea[aria-invalid="true"] {
            border-color: var(--error-dark);
        }
    }

    .testimonials-section {
        margin: 2rem 0;
        padding: 2rem 20px;
    }

    .testimonials-grid {
        grid-template-columns: 1fr;
        gap: 1.5rem;
    }

    footer > div {
        grid-template-columns: 1fr;
    }

    footer ul {
        flex-direction: column;
        gap: 0.75rem;
    }

    footer nav ul li {
        display: block;
        text-align: center;
        margin-bottom: 0.5rem;
    }

    .feature-card h3 {
        font-size: 1.1rem;
    }

    legend {
        font-size: 1.25rem;
        padding: 0 0.5rem;
    }
}

